// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the owner (who can call NETM) and is a valid account
        vm.assume(caller != address(0) && caller != address(this));

        // Fund caller with enough ETH to call getTokens
        vm.deal(caller, 1 ether);

        // Call NETM() first to initialize balances
        c.NETM();

        // Next, caller calls getTokens via the receive function (send ETH)
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0.01 ether}("");

        // The general rule: if the call succeeded (no revert), then caller must be blacklisted
        assertTrue(!success || c.blacklist(caller), "Caller should be blacklisted after getTokens");
    }
}

