contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address k) public {
        // The reference C's NETM() does not change blacklist; the buggy M sets blacklist[msg.sender]=true.
        // Drive: call NETM() from an arbitrary account
        vm.assume(k != address(0));
