pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Record blacklist status for a random address before calling NETM
        address k = address(uint160(uint256(keccak256(abi.encode(caller, 1)))));
        bool blacklistBefore = c.blacklist(k);

        // Drive NETM with the fuzzed caller
        vm.prank(caller);
        c.NETM();

        // Assert that blacklist of k did not become true unless it was already true
        assertTrue(c.blacklist(k) == blacklistBefore);
    }
}

