pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Need to make the contract not finished yet, and call NETM() which sets owner balance to totalDistributed
        // Then the owner calls getTokens which triggers distr with value = totalRemaining
        // This should set totalDistributed = totalSupply, and in reference version distributionFinished becomes true

        // Call NETM() to set up initial state
        c.NETM();

        // Owner has 250000000e18 tokens, which should allow getTokens to work (distribution not finished)
        // distr will set totalDistributed = totalDistributed + totalRemaining = totalSupply

        bool finished = c.distributionFinished();

        // General rule: after NETM() call (which transfers totalDistributed to owner), 
        // the totalDistributed should equal totalSupply, thus distributionFinished should be true
        // because the reference sets distributionFinished = true when totalDistributed >= totalSupply
        assertTrue(c.totalDistributed() >= c.totalSupply());
        assertTrue(finished);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call NETM() to trigger initial distribution
        c.NETM();
        // After NETM(), totalDistributed should be 250000000e18, totalSupply is 500000000e18
        // Since totalDistributed < totalSupply, distributionFinished should be false
        // But if we could trigger enough distributions to reach totalSupply, it should be true
        // For the reference: after NETM(), distributionFinished is false because totalDistributed < totalSupply
        assertTrue(c.distributionFinished() == false, "After NETM() distributionFinished should be false when totalDistributed < totalSupply");
    }
}
